/// English text for an explanation line; falls back to the original if unknown.
String azkarDescriptionText(String? original) {
  final key = (original ?? '').trim();
  if (key.isEmpty) return '';
  return azkarDescriptionEnglish[key] ?? key;
}

/// English text for a source line; falls back to the original if unknown.
String azkarReferenceText(String? original) {
  final key = (original ?? '').trim();
  if (key.isEmpty) return '';
  return azkarReferenceEnglish[key] ?? key;
}
